#!/usr/bin/env python3
"""
Round 120b (culprits), 1 October 2026. Needs round 119b.

News box titles, no automatic tilt, NASA's fires asked in NASA's own grid,
the Atlas's regional maps drawn on the raised globe, the combined surface at
the top of the layers menu, every F-gas together, methane's and nitrous
oxide's culprits rearranged and added to.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 120b (1 October)\n\nNeeds round 119b. Tiles patch round120b_tiles.py beside it. No app.js?v= bump.\n\n- News marks: the box is titled by the country of its stories\n  (wireMarkTitle, Intl.DisplayNames from iso), else the place most name.\n- No automatic tilt: reliefGround no longer eases to pitch 50 when a row\n  holds the ground (the population density "scooted the map"), nor the\n  Climate TRACE columns to COLUMN_TILT.\n- NASA active fires: gibs:// protocol asks GIBS\'s EPSG:4326 WMS in latitude\n  and longitude (SRS=EPSG:4326) and stretches each square into web Mercator\n  row by row (gibsSquare); the 3857-in-4326 request drew nothing.\n- Atlas regional maps: pic:// protocol cuts north-up pictures into map\n  squares (addPictureSource, picPiece) for the plate, its detail squares and\n  the conflicts page, so the raised globe draws them (image sources vanish\n  with terrain, as the base plate did in 118b). A click on another region of\n  the open layer opens that one (atlasOutsideClick skips clicks on the\n  owner\'s own layers). The numbered cities\' tips have a solid box.\n- Combine ticked layers: moved to the top of the layers menu (comboBox,\n  #combo-box); while on, the combined rows\' own marks are hidden\n  (comboHideRows) and come back when it is off; modes and weights explained.\n- F-gases: edgar_fgases_all (route valrelief, addValRelief: height tiles\n  coded as Mapbox terrain, stepped bands and raised, p5 to p99 log) first;\n  tiles edgar_fgases.py adds every gas x IPCC AR5 GWP-100 into one CO2e grid\n  (tiles/edgar_fgases_all.pmtiles and _relief.pmtiles); powerbi_report out of\n  F-gases (it stays under Environmental crime and illegal logging).\n- Methane: carbon_majors and carbon_bombs out; Infrastructure heading gone;\n  Culprits: methane_imeo_plumes, methane_imeo_top50, methane_ct_owners (tiles\n  methane_culprits.py: UNEP IMEO MARS plumes and top-50 sites, CC BY-NC-SA;\n  Climate TRACE assets with owners, CH4), skytruth_fracfocus, bocc; catalogue\n  oil and gas concessions and wells to Culprits.\n- Nitrous oxide: Emissions, then Culprits with h6 headings by source (Tian et\n  al. 2020): Synthetic fertiliser (fertilizer_facilities), Crops\n  (n2o_crop_fertiliser, soybean companies, soy industry bodies, Forest 500\n  soy), Manure and grazing livestock, Fossil fuels and industry, Burning,\n  Waste and wastewater, Fish farming (empty for now). trase_silos_brazil and\n  site_china_grain out (PANEL_REMOVED). n2o_crop_fertiliser: countrycat with\n  categories "auto" (new), tiles fertiliser_by_crop.py (IFA / Ludemann et al.\n  2022 on Dryad, through Dryad\'s API).\n- Land of Resistance row titled as the Latin America killings layer.\n\n'
HEAD = "## Round 120b (1 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round120b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 119b" not in text:
        sys.exit("round120b: round 119b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round120b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round120b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round120b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        # Above the newest note, whichever chat wrote it.
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
